import numpy as np
import pytest

from xarray import Dataset, concat
from xarray.core import dtypes

from . import assert_identical, requires_dask


@pytest.mark.parametrize("reverse", [False, True])
@pytest.mark.parametrize("data_vars", ["all", "different"])
@pytest.mark.parametrize("fill_value", [dtypes.NA, -99])
def test_concat_missing_scalar_variables(reverse, data_vars, fill_value):
    datasets = [Dataset({"a": 1}), Dataset({"b": 2})]
    missing = np.nan if fill_value is dtypes.NA else fill_value
    expected = Dataset({"a": ("x", [1, missing]), "b": ("x", [missing, 2])})
    if reverse:
        datasets.reverse()
        expected = expected.isel(x=slice(None, None, -1))
    result = concat(datasets, "x", data_vars=data_vars, fill_value=fill_value)
    assert_identical(result, expected)


@pytest.mark.parametrize("data_vars", ["all", "different", "minimal", ["a", "b"]])
@pytest.mark.parametrize("positions", [None, [[2, 3], [0], [1]]])
def test_concat_missing_variable_segments(data_vars, positions):
    datasets = [
        Dataset({"a": ("x", [1, 2])}, coords={"x": [10, 11]}),
        Dataset({"b": ("x", [3])}, coords={"x": [12]}),
        Dataset({"a": ("x", [4])}, coords={"x": [13]}),
    ]
    expected = Dataset(
        {"a": ("x", [1, 2, np.nan, 4]), "b": ("x", [np.nan, np.nan, 3, np.nan])},
        coords={"x": [10, 11, 12, 13]},
    )
    if positions is not None:
        expected = expected.isel(x=[2, 3, 0, 1])
    originals = [ds.copy(deep=True) for ds in datasets]
    result = concat(datasets, "x", data_vars=data_vars, positions=positions)
    assert_identical(result, expected)
    for ds, original in zip(datasets, originals):
        assert_identical(ds, original)


def test_concat_missing_variable_alignment():
    datasets = [
        Dataset({"a": ("y", [1, 2])}, coords={"y": [0, 1]}),
        Dataset({"b": ("y", [3, 4])}, coords={"y": [1, 2]}),
    ]
    expected = Dataset(
        {
            "a": (("x", "y"), [[1, 2, np.nan], [np.nan, np.nan, np.nan]]),
            "b": (("x", "y"), [[np.nan, np.nan, np.nan], [np.nan, 3, 4]]),
        },
        coords={"y": [0, 1, 2]},
    )
    assert_identical(concat(datasets, "x"), expected)


def test_concat_missing_unconcatenated_variable():
    datasets = [Dataset({"a": 1}), Dataset({"b": 2})]
    expected = Dataset({"a": 1, "b": 2})
    assert_identical(concat(datasets, "x", data_vars="minimal"), expected)


@requires_dask
def test_concat_missing_variable_lazy():
    import dask.array as da

    datasets = [Dataset({"a": ("x", da.arange(2, chunks=1))}), Dataset({"b": ("x", [3])})]
    result = concat(datasets, "x")
    assert isinstance(result.a.data, da.Array)
    expected = Dataset({"a": ("x", [0, 1, np.nan]), "b": ("x", [np.nan, np.nan, 3])})
    assert_identical(result.compute(), expected)

